    function testFuzz_property(address actor, uint256 proposalID) public {
        vm.assume(actor != address(0));
        VaultMock vault = new VaultMock();
        address vader = address(new VaderMock());
        address usdv = address(new ERC20Mock());
        c.init(vader, usdv, address(vault));
        vault.setWeight(actor, 100);
        vm.prank(actor);
        c.newGrantProposal(actor, 1);
        vm.assume(proposalID == 1);
        vm.prank(actor);
        uint256 returnedWeight = c.voteProposal(proposalID);
        assertEq(returnedWeight, 100);
    }
}

